// the low chicken-wire fence in front of the hen house (the buddies stay outside it)
const wireFence = () => { let s = ""; for (let i = 0; i < 24; i++) s += `<path d="M${-40 + i * 40} 852 l20 -30 l20 30 l-20 30z" fill="none" stroke="#8D97B2" stroke-width="2.5" opacity=".8"/>`; return `<g>${s}<path d="M-60 822 H940 M-60 884 H940" stroke="#5E6788" stroke-width="5"/>${[0, 235, 470, 705, 930].map((x) => `<rect x="${x - 7}" y="806" width="14" height="92" rx="5" fill="#8A5E34" stroke="#5E3F28" stroke-width="3"/>`).join("")}</g>`; };
/* the farm. o: nest (svg drawn on the straw), hen: {x, y, sit, bob} or null, tags, day (default true), items, wire (default true), cat (default true) */
function farmView(t, o = {}, cam = [1, 960, 540]) { const N = FARM.nest;
  return CAM(bg("farm") + (o.day === false ? "" : TF(FARM.day[0], FARM.day[1], 1, dayCard(21))) + (o.wall || "") + TF(N[0], N[1], .78, nestBox(o.nest || "", { tags: o.tags }))
    + (o.cat === false ? "" : TF(FARM.cat[0], FARM.cat[1], .62, catBasket(t))) + (o.wire === false ? "" : wireFence()) + (o.items || ""), cam[0], cam[1], cam[2]); }
// the hen sitting on her nest (drawn in nest coordinates), eggs just showing under her
const henOnNest = (t, o = {}) => (o.eggs === false ? "" : EGGX.map((x, i) => TF(x * .62, -108, .8, egg())).join("")) + TF(-10, -62, 1.5, hen({ sit: 1, bob: .3 * Math.sin(t * 1.3) }));
const lizOnWall = (t, hide = 0) => hide >= 1 ? "" : `<g transform="translate(${FARM.day[0] + 4} ${FARM.day[1] + 132}) rotate(-8) scale(${n2(.8 * (1 - hide))})"><g transform="rotate(${n2(3 * Math.sin(t * 5))})">${cicak()}</g></g>`;

/* ---------- Pip's list: his notebook on its little stand; three numbered drawings ---------- */
function snail(pull = 0, o = {}) { const k = 1 - .86 * eio(pull);
  return `<g transform="translate(-30 0) scale(${n2(k)} ${n2(lerp(1, .7, eio(pull)))})"><path d="M10 0 Q-60 4 -120 -4 Q-150 -10 -146 -34 Q-140 -52 -116 -44 Q-96 -30 -40 -30 L20 -30z" fill="#E8C89A" stroke="#A8845A" stroke-width="5" stroke-linejoin="round"/><path d="M-134 -44 l-14 -34 M-118 -46 l-4 -36" stroke="#A8845A" stroke-width="5" stroke-linecap="round"/><circle cx="-148" cy="-80" r="6" fill="${P.ink}"/><circle cx="-122" cy="-84" r="6" fill="${P.ink}"/><path d="M-138 -26 q8 6 16 0" fill="none" stroke="#7A5A36" stroke-width="3" stroke-linecap="round"/></g>
  <path d="M-50 0 H70 Q84 0 80 -10 L-40 -14z" fill="#E8C89A" stroke="#A8845A" stroke-width="5" stroke-linejoin="round"/><circle cx="14" cy="-62" r="62" fill="#C98A4E" stroke="#7A4A22" stroke-width="6"/><path d="M14 -62 m0 -44 a44 44 0 1 1 -44 44 a30 30 0 1 1 30 30 a17 17 0 1 1 17 -17" fill="none" stroke="#7A4A22" stroke-width="6" stroke-linecap="round"/><ellipse cx="-8" cy="-92" rx="14" ry="8" fill="#fff" opacity=".3"/>`; }
const iceCream = (melt = 1) => `<path d="M-34 -70 L0 40 L34 -70z" fill="#E8B86A" stroke="#A8742E" stroke-width="5" stroke-linejoin="round"/><path d="M-22 -50 L14 -8 M-8 -66 L24 -30 M22 -50 L-14 -8 M8 -66 L-24 -30" stroke="#A8742E" stroke-width="2.5" opacity=".6"/><circle cx="0" cy="-96" r="46" fill="#FF9FC0" stroke="#D9608A" stroke-width="5"/><ellipse cx="-14" cy="-112" rx="12" ry="8" fill="#fff" opacity=".5"/>
  ${melt ? `<path d="M-40 -84 q-4 44 -2 62 q6 14 12 0 q0 -30 4 -50z M26 -76 q2 30 2 50 q6 12 10 0 q2 -30 2 -54z" fill="#FF9FC0" stroke="#D9608A" stroke-width="4" stroke-linejoin="round"/><ellipse cx="-4" cy="52" rx="56" ry="11" fill="#FF9FC0" stroke="#D9608A" stroke-width="4"/>` : ""}`;
const sunHeat = () => `<circle r="26" fill="${P.sun}" stroke="#F59E0B" stroke-width="4"/>${[0, 45, 90, 135, 180, 225, 270, 315].map((a) => `<path d="M0 -36 v-14" stroke="#F59E0B" stroke-width="5" stroke-linecap="round" transform="rotate(${a})"/>`).join("")}`;
const doorPic = (sw = .5) => `<rect x="-70" y="-190" width="140" height="190" rx="6" fill="#5E4630"/><rect x="-70" y="-190" width="140" height="190" rx="6" fill="none" stroke="#C9B08A" stroke-width="10"/><g transform="translate(-64 0) scale(${n2(lerp(.55, .96, sw))} 1)"><rect x="0" y="-184" width="128" height="184" fill="#4E93B4" stroke="#2C6F92" stroke-width="5"/><rect x="16" y="-166" width="96" height="60" rx="6" fill="none" stroke="#2C6F92" stroke-width="4"/><rect x="16" y="-90" width="96" height="70" rx="6" fill="none" stroke="#2C6F92" stroke-width="4"/><circle cx="110" cy="-96" r="8" fill="${P.sun}"/></g>`;
const windLines = (t = 0) => `<g fill="none" stroke="#8D97B2" stroke-width="5" stroke-linecap="round">${[[-60, 0], [-30, 1], [0, 2]].map(([y, i]) => `<path d="M${n2(-150 + 14 * Math.sin(t * 6 + i))} ${y} h56 q16 0 16 -12 q0 -10 -10 -10"/>`).join("")}</g>`;
/* Pip's notebook on its stand. origin = the middle of its base; 1120 x 600. o.lit = [a, b, c]; o.marks = [null | ["x" | "tick", k], ..]; o.pull = the snail;
   o.cause = [0, k, k] (the labels "the heat melts it", "the wind pushes it", each joined by one plain line); o.tags = [k, k, k] (the tags under the drawings) */
const NBX = [-350, 0, 350];
function notebook(t, o = {}) { const lit = o.lit || [0, 0, 0], mk = o.marks || [], cz = o.cause || [0, 0, 0], tg = o.tags || [0, 0, 0]; let pan = "";
  const pics = [TF(44, 50, 1.0, snail(o.pull === undefined ? 1 : o.pull)) + TF(-96, -34, .46, `<g transform="rotate(-50)">${pointer()}</g>`), TF(-6, 6, .92, iceCream(1)) + TF(96, -112, .85, sunHeat()), TF(50, 96, .96, doorPic(.5 + .4 * Math.sin(t * 2.4))) + TF(18, 30, .8, windLines(t))];
  const cause = [null, ["the heat melts it", 96, -84], ["the wind pushes it", -100, 40]], tags = [["living thing · it responds", "#1F8A4C"], ["non-living thing", "#4A3F6B"], ["non-living thing", "#4A3F6B"]];
  NBX.forEach((x, i) => { pan += `<g transform="translate(${x} -330) scale(${n2(1 + .05 * lit[i])})">${lit[i] > .05 ? `<rect x="-166" y="-180" width="332" height="360" rx="30" fill="${P.sun}" opacity="${n2(.85 * lit[i])}" filter="url(#b10)"/>` : ""}<rect x="-156" y="-170" width="312" height="340" rx="22" fill="#fff" stroke="#C9D2E8" stroke-width="5"/>${pics[i]}
    ${cause[i] && cz[i] > .02 ? OP(Math.min(1, cz[i]), `<path d="M${cause[i][1]} 112 V${cause[i][2]}" stroke="${P.ink}" stroke-width="4" stroke-linecap="round"/><circle cx="${cause[i][1]}" cy="${cause[i][2]}" r="6" fill="${P.ink}"/>`) + TF(0, 130, Math.min(1.05, cz[i]), tpill(0, 0, cause[i][0], 27, P.ink, "#fff", { w: 600, nosh: true })) : ""}
    <g transform="translate(-118 -134)"><circle r="30" fill="${P.pip}"/>${T(0, 14, i + 1, 40, "#fff")}</g>${mk[i] ? TF(-58, -134, mk[i][1], mk[i][0] === "x" ? xBadge(24) : tickBadge(26)) : ""}</g>${tg[i] > .02 ? TF(x, -122, Math.min(1.05, tg[i]), tpill(0, 0, tags[i][0], 26, tags[i][1], "#fff", { w: 700, nosh: true })) : ""}`; });
  return `<ellipse cx="0" cy="4" rx="300" ry="18" fill="${P.ink}" opacity=".22" filter="url(#b4)"/><path d="M-120 0 L-40 -110 M120 0 L40 -110" stroke="#8A5A36" stroke-width="16" stroke-linecap="round"/><rect x="-170" y="-14" width="340" height="20" rx="10" fill="#8A5A36"/>
  <g filter="url(#drop)"><rect x="-560" y="-640" width="1120" height="570" rx="30" fill="${P.pip}"/><rect x="-540" y="-622" width="1080" height="534" rx="18" fill="url(#gPaper)"/></g>${[-420, -280, -140, 0, 140, 280, 420].map((x) => `<rect x="${x - 8}" y="-660" width="16" height="44" rx="8" fill="#AAB3CC" stroke="#5E6788" stroke-width="4"/>`).join("")}
  ${T(0, -552, "THINGS THAT RESPONDED TODAY", 44, P.ink, { ls: 2 })}${pan}`; }

/* ---------- the same person growing up: baby, child, teenager, adult. origin = feet. a = 0..3 ---------- */
function person(a) { const H = [150, 250, 340, 400][a], hr = [40, 44, 46, 48][a], leg = [34, 92, 150, 186][a], tor = [52, 78, 98, 112][a], arm = [34, 70, 104, 124][a], wd = [50, 62, 72, 84][a], hy = -(leg + tor + hr * .86), hair = "#3A2A22", shirt = "#2EC4B6";
  const hairS = a === 0 ? `<path d="M-6 ${n2(hy - hr)} q6 -16 14 -4" fill="none" stroke="${hair}" stroke-width="6" stroke-linecap="round"/>` : a === 1 ? `<path d="M${-hr} ${n2(hy - 6)} Q${-hr - 2} ${n2(hy - hr - 12)} 0 ${n2(hy - hr - 8)} Q${hr + 2} ${n2(hy - hr - 12)} ${hr} ${n2(hy - 6)} Q${hr * .6} ${n2(hy - hr * .6)} 0 ${n2(hy - hr * .58)} Q${-hr * .6} ${n2(hy - hr * .6)} ${-hr} ${n2(hy - 6)}z" fill="${hair}"/>`
    : `<path d="M${-hr - 4} ${n2(hy + (a === 3 ? 44 : 26))} Q${-hr - 12} ${n2(hy - hr - 16)} 0 ${n2(hy - hr - 10)} Q${hr + 12} ${n2(hy - hr - 16)} ${hr + 4} ${n2(hy + (a === 3 ? 44 : 26))} Q${hr - 4} ${n2(hy - hr * .5)} 0 ${n2(hy - hr * .56)} Q${-hr + 4} ${n2(hy - hr * .5)} ${-hr - 4} ${n2(hy + (a === 3 ? 44 : 26))}z" fill="${hair}"/>`;
  const teeth = a === 0 ? `<path d="M-9 ${n2(hy + 16)} q9 9 18 0" fill="none" stroke="#8E3A4A" stroke-width="4" stroke-linecap="round"/>` : `<path d="M-13 ${n2(hy + 13)} q13 16 26 0z" fill="#8E3A4A"/><rect x="-9" y="${n2(hy + 13)}" width="18" height="6" rx="2" fill="#fff"/>${a === 1 ? `<rect x="-2" y="${n2(hy + 13)}" width="5" height="6" fill="#8E3A4A"/>` : ""}`;
  return `<ellipse cx="0" cy="3" rx="${wd}" ry="9" fill="${P.ink}" opacity=".22" filter="url(#b4)"/>${[-1, 1].map((s) => `<rect x="${n2(s * wd * .3 - 12)}" y="${-leg}" width="24" height="${leg}" rx="11" fill="${a ? "#34406E" : SKIN}" stroke="${a ? "#232C52" : SKIN2}" stroke-width="4"/><rect x="${n2(s * wd * .3 - 16)}" y="-16" width="34" height="18" rx="8" fill="#fff" stroke="#8D97B2" stroke-width="4"/>`).join("")}
  ${[-1, 1].map((s) => `<g transform="translate(${n2(s * wd * .5)} ${-(leg + tor) + 10}) rotate(${-s * 12})"><rect x="-11" y="0" width="22" height="${arm}" rx="11" fill="${SKIN}" stroke="${SKIN2}" stroke-width="4"/></g>`).join("")}
  <rect x="${-wd / 2}" y="${-(leg + tor)}" width="${wd}" height="${tor + 8}" rx="18" fill="${shirt}" stroke="#1E9488" stroke-width="4"/><circle cx="0" cy="${n2(hy)}" r="${hr}" fill="${SKIN}" stroke="${SKIN2}" stroke-width="4"/>${hairS}
  <circle cx="${-hr * .36}" cy="${n2(hy - 2)}" r="5.5" fill="${P.ink}"/><circle cx="${hr * .36}" cy="${n2(hy - 2)}" r="5.5" fill="${P.ink}"/><ellipse cx="${-hr * .62}" cy="${n2(hy + 12)}" rx="8" ry="5" fill="#FF9CA8" opacity=".55"/><ellipse cx="${hr * .62}" cy="${n2(hy + 12)}" rx="8" ry="5" fill="#FF9CA8" opacity=".55"/>${teeth}`; }
const PERSON_H = [150, 250, 340, 400].map((h, a) => [34, 92, 150, 186][a] + [52, 78, 98, 112][a] + [40, 44, 46, 48][a] * 1.86);

/* ---------- Basil's trail notes on a small easel; 900 x 640; origin = the middle of the easel's feet ---------- */
function trailNotes(t, o = {}) { const lit = o.lit || [0, 0, 0], L3 = o.fixed ? "A fern reproduces through spores." : "A fern, by producing seeds.", rub = o.rub || 0, wr = o.write === undefined ? 1 : o.write;
  const rows = [["A hen reproduces by laying eggs.", TF(0, 26, .26, hen())], ["A tomato plant, by producing seeds.", TF(0, 0, .5, tomato())], [L3, `<g transform="translate(-40 8) rotate(-22) scale(.19)">${fernLeaf(o.fixed)}</g>`]]; let s = "";
  rows.forEach(([txt, pic], i) => { const y = -610 + i * 150, hide = i === 2 && o.fixing; s += `<g transform="translate(0 ${y})">${lit[i] > .05 ? `<rect x="-420" y="-64" width="840" height="128" rx="24" fill="${P.sun}" opacity="${n2(.55 * lit[i])}"/>` : ""}<g transform="translate(-370 0) scale(${n2(1 + .18 * (o.badge || [0, 0, 0])[i])})"><circle r="38" fill="${P.basil}"/>${T(0, 17, i + 1, 50, "#fff")}</g>
    ${hide ? `<text x="-300" y="16" font-family="Fredoka" font-weight="600" font-size="38" fill="${P.ink}" opacity="${n2(1 - rub)}">${esc("A fern, by producing seeds.")}</text><text x="-300" y="16" font-family="Fredoka" font-weight="600" font-size="38" fill="#1F8A4C" style="clip-path:inset(-30px ${n2(100 - 100 * wr)}% -30px 0)">${esc("A fern reproduces through spores.")}</text>` : `<text x="-300" y="16" font-family="Fredoka" font-weight="600" font-size="38" fill="${i === 2 && o.fixed ? "#1F8A4C" : P.ink}">${esc(txt)}</text>`}
    ${i < 2 || !o.fixed ? "" : ""}<g transform="translate(418 0)">${i === 2 && (o.fixed || o.fixing) ? "" : pic}</g>${i === 2 && o.x ? TF(-448, 0, o.x, xBadge(26)) : ""}</g><path d="M-410 ${y + 74} H410" stroke="${P.ink2}" stroke-width="2.5" stroke-dasharray="3 9" opacity=".4"/>`; });
  return `<ellipse cx="0" cy="4" rx="330" ry="18" fill="${P.ink}" opacity=".22" filter="url(#b4)"/><path d="M-200 0 L-90 -400 M200 0 L90 -400 M0 0 V-300" stroke="#8A5A36" stroke-width="16" stroke-linecap="round"/><rect x="-330" y="-176" width="660" height="20" rx="10" fill="#8A5A36"/>
  <g filter="url(#drop)"><rect x="-480" y="-810" width="960" height="640" rx="26" fill="url(#gPaper)" stroke="${P.basil}" stroke-width="8"/></g>${T(-40, -716, "How do they reproduce?", 56, P.ink)}<g transform="translate(400 -734) rotate(14) scale(.9)" opacity=".8"><circle r="34" fill="none" stroke="${P.basil}" stroke-width="4" stroke-dasharray="5 5"/>${[-18, -6, 6, 18].map((x, j) => `<ellipse cx="${x}" cy="${-10 - (j % 3 ? 6 : 0)}" rx="4.5" ry="8" fill="${P.basil}"/>`).join("")}<ellipse cx="0" cy="10" rx="13" ry="10" fill="${P.basil}"/></g>${s}
  ${o.tick ? TF(410, -250, o.tick, tickBadge(40)) : ""}`; }

/* ---------- a round bus on the road (the cliffhanger); origin = the road under its middle ---------- */
function bus(t, discs = "") { const wh = (x) => `<g transform="translate(${x} -34)"><circle r="46" fill="${P.ink}"/><circle r="24" fill="#C9D2E8"/><g transform="rotate(${n2(t * 400)})"><path d="M-24 0 H24 M0 -24 V24" stroke="#8D97B2" stroke-width="6"/></g></g>`;
  return `<ellipse cx="0" cy="12" rx="560" ry="18" fill="${P.ink}" opacity=".25" filter="url(#b4)"/><g transform="translate(0 ${n2(3 * Math.sin(t * 9))})"><g filter="url(#drop)"><rect x="-540" y="-430" width="1080" height="390" rx="50" fill="url(#fBus)" stroke="#5E6788" stroke-width="7"/></g><rect x="-540" y="-150" width="1080" height="64" fill="#2FA65A"/><rect x="-540" y="-86" width="1080" height="18" fill="#FFC83A"/>
  ${[-400, -130, 140].map((x) => `<rect x="${x - 110}" y="-392" width="230" height="210" rx="26" fill="#BFE6FF" stroke="#5E6788" stroke-width="6"/>`).join("")}<rect x="300" y="-392" width="200" height="330" rx="22" fill="#DDF1FF" stroke="#5E6788" stroke-width="6"/><path d="M400 -392 V-62" stroke="#5E6788" stroke-width="5"/>${discs}
  ${[-400, -130, 140].map((x) => `<rect x="${x - 110}" y="-200" width="230" height="20" rx="8" fill="#5E6788"/><rect x="${x - 104}" y="-386" width="60" height="150" rx="16" fill="#fff" opacity=".25"/>`).join("")}<rect x="-520" y="-470" width="300" height="52" rx="14" fill="${P.ink}"/>${T(-370, -432, "KRANJI", 38, P.sun, { ls: 6 })}</g>${wh(-340)}${wh(300)}`; }
